function LiveTicker() {
  const [price, setPrice] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      fetch('/api/price').then(r => r.json()).then(setPrice);
    }, 1000);
    return () => clearInterval(id); // cleanup on unmount
  }, []);

  return <div>Price: {price}</div>;
}
